510.     /// Attempts to handle a page fault as a copy-on-write fault.
511.     ///
512.     /// A page fault is treated as a copy-on-write fault when it is a user-mode write to
513.     /// a present page whose PTE has the AVL copy-on-write bit set. In that case this
514.     /// function allocates a private frame for the faulting address, copies the contents
515.     /// of the shared frame into it, and points the faulting PTE at the new frame with
516.     /// the writable bit restored and the copy-on-write bit cleared. The reference held
517.     /// on the old shared frame is then released.
518.     ///
519.     /// # Parameters
520.     ///
521.     /// - `vmem`: Virtual memory space of the faulting process.
522.     /// - `fault_addr`: Faulting virtual address (need not be page-aligned).
523.     /// - `error_code`: Typed x86 page-fault error code.
524.     ///
525.     /// # Returns
526.     ///
527.     /// - `Ok(true)` if the fault was resolved as a copy-on-write fault.
528.     /// - `Ok(false)` if the fault is not a copy-on-write fault and should be forwarded
529.     ///   to the registered handler.
530.     /// - `Err(_)` if the fault was a copy-on-write fault but resolving it failed.
531.     ///
532.     pub fn try_resolve_cow_fault(
533.         &mut self,
534.         vmem: &mut Vmem,
535.         fault_addr: usize,
536.         error_code: ::arch::cpu::excp::ErrorCode,
537.     ) -> Result<bool, Error> {
538.         // Copy-on-write faults are user-mode writes to a present page.
539.         if !error_code.is_present() || !error_code.is_write() || !error_code.is_user() {
540.             return Ok(false);
541.         }
542. 
543.         // Reject addresses that are not in user space outright. We must do this before
544.         // touching `vmem` so that bogus addresses do not error out.
545.         let page_addr: usize = ::sys::mm::align_down(fault_addr, PAGE_ALIGNMENT);
546.         let vaddr: PageAligned<VirtualAddress> = match PageAligned::from_raw_value(page_addr) {
547.             Ok(v) => v,
548.             Err(_) => return Ok(false),
549.         };
550. 
551.         // Delegate to the shared resolver. It returns `Ok(false)` if the page is not
552.         // copy-on-write (in which case the fault is forwarded to the registered handler)
553.         // and `Ok(true)` if a copy-on-write mapping was resolved.
554.         vmem.resolve_cow_at(vaddr)
555.     }
556. 
557.     ///
558.     /// # Description
559.     ///
560.     /// Attempts to unmap a user page from the target virtual memory space.
561.     ///
562.     /// # Parameters
563.     ///
564.     /// - `vmem`: Virtual memory space where the page is mapped.
565.     /// - `vaddr`: Virtual address of the page to be unmapped.
566.     ///
567.     /// # Return Values
568.     ///
569.     /// - `Ok(true)` if the page was present and has been unmapped.
570.     /// - `Ok(false)` if the page was not present.
571.     /// - `Err(_)` on unexpected failures.
572.     ///
573.     pub fn try_unmap_upage(
574.         &mut self,
575.         vmem: &mut Vmem,
576.         vaddr: PageAligned<VirtualAddress>,
577.     ) -> Result<bool, Error> {
578.         // The returned `UserFrame` is dropped here, which frees the underlying physical frame.
579.         Ok(vmem.unmap(vaddr)?.is_some())
580.     }
581. 
582.     ///
583.     /// # Description
584.     ///
585.     /// Allocates and maps user pages into a virtual address space.
586.     ///
587.     /// # Parameters
588.     ///
589.     /// - `vmem`: Virtual memory space where pages are mapped.
590.     /// - `vaddr`: Starting virtual address for the mapping.
591.     /// - `access`: Access permissions for the mapped pages.
592.     /// - `clear`: Clear pages after mapping?
593.     /// - `nframes`: Number of pages to allocate.
594.     /// - `uframes`: Mutable reference to a pre-allocated vector for temporary frame storage.
595.     ///
596.     /// # Return Values
597.     ///
598.     /// Upon success, `Ok(())` is returned. Upon failure, all successfully mapped pages are rolled
599.     /// back and an error is returned instead.
600.     ///
601.     pub fn alloc_upages(
602.         &mut self,
603.         vmem: &mut Vmem,
604.         mut vaddr: PageAligned<VirtualAddress>,
605.         access: AccessPermission,
606.         clear: bool,
607.         nframes: usize,
608.         uframes: &mut Vec<UserFrame>,
609.     ) -> Result<(), Error> {
610.         trace!("vaddr={:?}, nframes={}", vaddr, nframes);
611. 
612.         // The caller-supplied buffer must be empty; stale frames would cause double-mapping.
613.         if !uframes.is_empty() {
614.             let reason: &str = "caller-supplied uframes vector is not empty";
615.             error!("{reason}");
616.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
617.         }
618.         if uframes.capacity() < nframes {
619.             let reason: &str = "caller-supplied uframes vector has insufficient capacity";
620.             error!("{reason}");
621.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
622.         }
623. 
624.         // Validate that nframes is positive and the full range lies in user space.
625.         let range_size: usize = nframes.checked_mul(mem::PAGE_SIZE).ok_or_else(|| {
626.             let reason: &str = "range size overflow";
627.             error!("{reason} (nframes={nframes})");
628.             Error::new(ErrorCode::InvalidArgument, reason)
629.         })?;
630.         if !Vmem::is_user_region(vaddr.into_inner(), range_size) {
631.             let reason: &str = "range is not entirely in user space";
632.             error!("{reason} (vaddr={vaddr:?}, nframes={nframes})");
633.             return Err(Error::new(ErrorCode::BadAddress, reason));
634.         }
635. 
636.         // Check that none of the pages in the range are already mapped.
637.         let mut check_addr: PageAligned<VirtualAddress> = vaddr;
638.         let mut checked_count: usize = 0;
639.         while checked_count < nframes {
640.             if vmem.is_user_page_mapped(check_addr)? {
641.                 let reason: &str = "page already mapped in range";
642.                 error!("{reason} (vaddr={check_addr:?})");
643.                 return Err(Error::new(ErrorCode::ResourceBusy, reason));
644.             }
645.             check_addr = PageAligned::from_raw_value(
646.                 check_addr
647.                     .into_raw_value()
648.                     .checked_add(mem::PAGE_SIZE)
649.                     .ok_or_else(|| {
650.                         let reason: &str = "address overflow in range check";
651.                         error!("{reason} (check_addr={check_addr:?})");
652.                         Error::new(ErrorCode::BadAddress, reason)
653.                     })?,
654.             )?;
655.             checked_count += 1;
656.         }
657. 
658.         // SAFETY: the kernel is single-threaded and runs with interrupts disabled; no concurrent
659.         // or re-entrant access to the physical memory manager is possible.
660.         let alloc_result: Result<(), Error> =
661.             unsafe { PhysMemoryManager::get_mut() }.alloc_many_user_frames(nframes, uframes);
662.         if let Err(e) = alloc_result {
663.             uframes.clear();
664.             return Err(e);
665.         }
666. 
667.         let start_vaddr: PageAligned<VirtualAddress> = vaddr;
668.         let mut mapped_count: usize = 0;
669.         let mut map_error: Result<(), Error> = Ok(());
670. 
671.         {
672.             let mut drain = uframes.drain(..);
673.             loop {
674.                 let uframe: UserFrame = match drain.next() {
675.                     Some(uframe) => uframe,
676.                     None => break,
677.                 };
678. 
679.                 if let Err(e) = vmem.map(uframe, vaddr, access) {
680.                     map_error = Err(e);
681.                     break;
682.                 }
683.                 mapped_count += 1;
684.                 if clear {
685.                     if let Err(e) = vmem.memset(vaddr, 0) {
686.                         map_error = Err(e);
687.                         break;
688.                     }
689.                 }
690.                 match PageAligned::from_raw_value(vaddr.into_raw_value() + mem::PAGE_SIZE) {
691.                     Ok(next) => vaddr = next,
692.                     Err(e) => {
693.                         map_error = Err(e);
694.                         break;
695.                     },
696.                 }
697.             }
698.         }
699. 
700.         if let Err(e) = map_error {
701.             // Rollback: unmap all pages that were successfully mapped.
702.             let mut rollback_addr: PageAligned<VirtualAddress> = start_vaddr;
703.             let mut rollback_count: usize = 0;
704.             while rollback_count < mapped_count {
705.                 if let Err(re) = self.try_unmap_upage(vmem, rollback_addr) {
706.                     warn!(
707.                         "alloc_upages(): rollback failed (vaddr={rollback_addr:?}, error={re:?})"
708.                     );
709.                 }
710.                 rollback_addr = match PageAligned::from_raw_value(
711.                     rollback_addr.into_raw_value() + mem::PAGE_SIZE,
712.                 ) {
713.                     Ok(next) => next,
714.                     Err(_) => break,
715.                 };
716.                 rollback_count += 1;
717.             }
718.             return Err(e);
719.         }
720. 
721.         Ok(())
722.     }
723. 
724.     ///
725.     /// # Description
726.     ///
727.     /// Changes the access permissions of a user page.
728.     ///
729.     /// # Parameters
730.     ///
731.     /// - `vmem`: Virtual memory space where the page is mapped.
732.     /// - `vaddr`: Virtual address of the page to be controlled.
733.     /// - `access`: Access permissions.
734.     ///
735.     /// # Return Values
736.     ///
737.     /// Upon success, empty is returned. Upon failure, an error is returned instead.
738.     ///
739.     pub fn ctrl_upage(
740.         &mut self,
741.         vmem: &mut Vmem,
742.         vaddr: PageAligned<VirtualAddress>,
743.         access: AccessPermission,
744.     ) -> Result<(), Error> {
745.         vmem.uctrl(vaddr, access)
746.     }
747. 
748.     ///
749.     /// # Description
750.     ///
751.     /// Allocates a kernel page.
752.     ///
753.     /// # Parameters
754.     ///
755.     /// - `clear`: Clear page?
756.     ///
757.     /// # Return Values
758.     ///
759.     /// Upon success, a kernel page is returned. Upon failure, an error is returned instead.
760.     ///
761.     pub fn alloc_kpage(&mut self, clear: bool) -> Result<KernelPage, Error> {
762.         // SAFETY: the kernel is single-threaded and runs with interrupts disabled; no concurrent
763.         // or re-entrant access to the physical memory manager is possible.
764.         let mut kframe: KernelFrame =
765.             unsafe { PhysMemoryManager::get_mut() }.alloc_kernel_frame()?;
766.         if clear {
767.             kframe.clear()?;
768.         }
769.         Ok(KernelPage::new(kframe))
770.     }
771. 
772.     ///
773.     /// # Description
774.     ///
775.     /// Allocates a contiguous range of kernel frames into caller-provided storage.
776.     ///
777.     /// # Parameters
778.     ///
779.     /// - `clear`: Clear frames?
780.     /// - `count`: Number of frames to allocate.
781.     /// - `kframes`: Pre-allocated vector where allocated frames are placed. It
782.     ///   must have sufficient capacity for `count` entries.
783.     ///
784.     /// # Return Values
785.     ///
786.     /// Upon success, `Ok(())` is returned and `kframes` is filled with `count`
787.     /// frames. Upon failure, an error is returned instead.
788.     ///
789.     pub fn alloc_kpages(
790.         &mut self,
791.         clear: bool,
792.         count: usize,
793.         kframes: &mut Vec<KernelFrame>,
794.     ) -> Result<(), Error> {
795.         if !kframes.is_empty() {
796.             let reason: &str = "caller-supplied kframes vector is not empty";
797.             error!("{reason}");
798.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
799.         }
800.         if kframes.capacity() < count {
801.             let reason: &str = "caller-supplied kframes vector has insufficient capacity";
802.             error!("{reason}");
803.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
804.         }
805. 
806.         // SAFETY: the kernel is single-threaded and runs with interrupts disabled; no concurrent
807.         // or re-entrant access to the physical memory manager is possible.
808.         unsafe { PhysMemoryManager::get_mut() }.alloc_many_kernel_frames(count, kframes)?;
809.         if clear {
810.             let clear_result = kframes.iter_mut().try_for_each(|kframe| kframe.clear());
811.             if let Err(e) = clear_result {
812.                 // Drop all allocated frames to free them back to the physical memory manager.
813.                 kframes.clear();
814.                 return Err(e);
815.             }
816.         }
817. 
818.         Ok(())
819.     }
820. 
821.     /// Load an ELF image into a virtual address space.
822.     pub fn load_elf(
823.         &mut self,
824.         vmem: &mut Vmem,
825.         elf: &Elf32Fhdr,
826.     ) -> Result<(VirtualAddress, PageAligned<VirtualAddress>), Error> {
827.         elf::elf32_load(self, vmem, elf)
828.     }
829. }
